import { Composio } from '@composio/core';

const composio = new Composio({ apiKey: process.env.COMPOSIO_API_KEY });
const userId = process.env.ZION_USER_ID || 'zion-billing';

const connections = {
  stripe: process.env.COMPOSIO_STRIPE_CONNECTION_ID,
  resend: process.env.COMPOSIO_RESEND_CONNECTION_ID,
  slack: process.env.COMPOSIO_SLACK_CONNECTION_ID,
  hubspot: process.env.COMPOSIO_HUBSPOT_CONNECTION_ID,
};

async function executeTool(name, toolSlug, connectionId, args = {}) {
  if (!connectionId) return { skipped: true };
  try {
    const result = await composio.tools.execute(toolSlug, {
      connectionId,
      entity_id: userId,
      arguments: args,
    });
    return { ok: true, result };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

async function run() {
  const ts = new Date().toISOString();
  console.log(`\n═══ ZION BILLING AUTOMATION v1.0 — ${ts} ═══\n`);

  const summary = { timestamp: ts, invoices: [], customers: [], notifications: [] };

  // 1. LIST RECENT CUSTOMERS
  console.log('→ Stripe: listing customers');
  const customers = await executeTool('stripe', 'STRIPE_LIST_CUSTOMERS', connections.stripe, { limit: 20 });
  if (customers.ok) {
    const data = customers.result?.data || [];
    summary.customers = data.map(c => ({ id: c.id, email: c.email, name: c.name }));
    console.log(`  ${data.length} customers found`);
  }

  // 2. LIST RECENT CHARGES
  console.log('→ Stripe: listing charges');
  const charges = await executeTool('stripe', 'STRIPE_LIST_CHARGES', connections.stripe, { limit: 20 });
  if (charges.ok) {
    const data = charges.result?.data || [];
    const totalCents = data.reduce((s, c) => s + (c.amount || 0), 0);
    summary.charges = { count: data.length, totalCents, totalUSD: (totalCents / 100).toFixed(2) };
    console.log(`  ${data.length} charges, total: $${(totalCents / 100).toFixed(2)}`);
  }

  // 3. LIST SUBSCRIPTIONS
  console.log('→ Stripe: listing subscriptions');
  const subs = await executeTool('stripe', 'STRIPE_LIST_SUBSCRIPTIONS', connections.stripe, { limit: 20, status: 'active' });
  if (subs.ok) {
    const data = subs.result?.data || [];
    summary.subscriptions = { count: data.length, active: data.filter(s => s.status === 'active').length };
    console.log(`  ${data.length} subscriptions (${summary.subscriptions.active} active)`);
  }

  // 4. CALCULATE MRR
  if (subs.ok && charges.ok) {
    const activeSubs = subs.result?.data?.filter(s => s.status === 'active') || [];
    let mrr = 0;
    for (const sub of activeSubs) {
      const items = sub.items?.data || [];
      for (const item of items) {
        const price = item.price || {};
        const amount = price.unit_amount || 0;
        const interval = price.recurring?.interval || 'month';
        const quantity = item.quantity || 1;
        if (interval === 'month') mrr += amount * quantity;
        else if (interval === 'year') mrr += (amount * quantity) / 12;
      }
    }
    summary.mrr = { cents: mrr, usd: (mrr / 100).toFixed(2) };
    console.log(`  Estimated MRR: $${(mrr / 100).toFixed(2)}`);
  }

  // 5. HUBSPOT: SYNC DEALS
  console.log('→ HubSpot: fetching deals');
  const deals = await executeTool('hubspot', 'HUBSPOT_FETCH_DEALS', connections.hubspot, { limit: 10 });
  if (deals.ok) {
    summary.deals = (deals.result?.data || []).length;
    console.log(`  ${summary.deals} deals in pipeline`);
  }

  // 6. SEND CEO REPORT VIA RESEND
  console.log('→ Resend: sending CEO report');
  const reportText = `Zion Billing Report (${ts.slice(0, 10)})

REVENUE:
- Active subscriptions: ${summary.subscriptions?.active || 0}
- Estimated MRR: $${summary.mrr?.usd || '0.00'}
- Total charges: ${summary.charges?.count || 0} ($${summary.charges?.totalUSD || '0.00'})

PIPELINE:
- HubSpot deals: ${summary.deals || 0}
- Customers: ${summary.customers.length}

Generated by Zion Billing Automation`;

  await executeTool('resend', 'RESEND_SEND_EMAIL', connections.resend, {
    from: 'Zion Tech Group <noreply@ziontechgroup.com>',
    to: ['kleber@ziontechgroup.com'],
    subject: `[Zion] Billing Report — ${ts.slice(0, 10)}`,
    text: reportText,
  });

  // 7. SLACK NOTIFICATION
  console.log('→ Slack: notifying ops');
  await executeTool('slack', 'SLACK_SEND_MESSAGE', connections.slack, {
    channel: process.env.SLACK_CHANNEL || '#ops',
    text: `💰 Zion Billing: MRR $${summary.mrr?.usd || '0'} | ${summary.subscriptions?.active || 0} active subs | ${summary.deals || 0} deals`,
  });

  console.log('\n═══ BILLING AUTOMATION COMPLETE ═══');
  console.log(JSON.stringify(summary, null, 2));
  return summary;
}

run().catch(e => { console.error('FATAL:', e); process.exit(1); });
